// Small compatibility wrapper so the rest of the application can keep its
// existing prepare().get()/all()/run() structure while the actual database
// is PostgreSQL hosted by Supabase.
function pgSql(sql, params = []) {
  let i = 0;
  return sql
    .replace(/INSERT\s+OR\s+IGNORE\s+INTO/ig, 'INSERT INTO')
    .replace(/\?/g, () => `$${++i}`)
    .replace(/\s+ON\s+CONFLICT\s+DO\s+NOTHING/ig, ' ON CONFLICT DO NOTHING');
}

const db = {
  prepare(sql) {
    return {
      async get(...params) {
        const q = pgSql(sql, params);
        const { rows } = await pool.query(q, params);
        return rows[0];
      },
      async all(...params) {
        const q = pgSql(sql, params);
        const { rows } = await pool.query(q, params);
        return rows;
      },
      async run(...params) {
        let q = pgSql(sql, params);
        const isInsert = /^\s*INSERT\b/i.test(q);
        const ignore = /INSERT\s+OR\s+IGNORE/i.test(sql);
        if (ignore && !/\bON\s+CONFLICT\b/i.test(q)) q += ' ON CONFLICT DO NOTHING';
        if (isInsert && !/\bRETURNING\b/i.test(q)) q += ' RETURNING *';
        const { rows, rowCount } = await pool.query(q, params);
        return { changes: rowCount, lastInsertRowid: rows[0]?.id, rows };
      }
    };
  },
  async exec(sql) { return pool.query(sql); },
  async close() { await pool.end(); }
};

