class SupabaseSessionStore extends session.Store {
  get(sid, cb) {
    (async () => {
      const row = await db.prepare('SELECT data,expires_at FROM sessions WHERE sid=?').get(sid);
      if (!row) return cb(null, null);
      if (row.expires_at && Number(row.expires_at) < Date.now()) {
        await db.prepare('DELETE FROM sessions WHERE sid=?').run(sid);
        return cb(null, null);
      }
      cb(null, typeof row.data === 'string' ? JSON.parse(row.data) : row.data);
    })().catch(cb);
  }
  set(sid, sess, cb) {
    (async () => {
      const exp = sess.cookie && sess.cookie.expires ? new Date(sess.cookie.expires).getTime() : (sess.cookie && sess.cookie.maxAge ? Date.now() + sess.cookie.maxAge : null);
      await db.prepare('INSERT INTO sessions(sid,data,expires_at) VALUES(?,?,?) ON CONFLICT(sid) DO UPDATE SET data=excluded.data,expires_at=excluded.expires_at').run(sid, JSON.stringify(sess), exp);
      cb(null);
    })().catch(cb);
  }
  destroy(sid, cb) { (async () => { await db.prepare('DELETE FROM sessions WHERE sid=?').run(sid); cb(null) })().catch(cb) }
  touch(sid, sess, cb) { (async () => { const exp = sess.cookie && sess.cookie.expires ? new Date(sess.cookie.expires).getTime() : (sess.cookie && sess.cookie.maxAge ? Date.now() + sess.cookie.maxAge : null); await db.prepare('UPDATE sessions SET expires_at=? WHERE sid=?').run(exp, sid); cb(null) })().catch(cb) }
}

