const storage = multer.memoryStorage();

const upload = multer({
  storage,
  limits: {
    fileSize: 1024 * 1024,
    files: 2
  },
  fileFilter: (req, file, cb) => {
    const allowed = [
      'image/jpeg',
      'image/jpg',
      'application/pdf'
    ];

    if (allowed.includes(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error(
        'Only JPG/JPEG and PDF files are allowed. Maximum 1 MB per file.'
      ));
    }
  }
});

const playerUpload = multer({
  storage,

  limits: {
    fileSize: 1024 * 1024,
    files: 2
  },

  fileFilter: (req, file, cb) => {

    if (file.fieldname === 'photo') {
      if (['image/jpeg', 'image/jpg'].includes(file.mimetype)) {
        return cb(null, true);
      }

      return cb(
        new Error('Player photo must be JPG/JPEG and maximum 1 MB.')
      );
    }

    if (file.fieldname === 'document') {
      if (
        ['image/jpeg', 'image/jpg', 'application/pdf']
          .includes(file.mimetype)
      ) {
        return cb(null, true);
      }

      return cb(
        new Error('Player document must be JPG/JPEG/PDF and maximum 1 MB.')
      );
    }

    return cb(
      new multer.MulterError(
        'LIMIT_UNEXPECTED_FILE',
        file.fieldname
      )
    );
  }
});
function storageBucket(kind) { return kind === 'private' ? PRIVATE_BUCKET : PUBLIC_BUCKET; }
function storageFilename(file) {
  const ext = path.extname(file?.originalname || '').toLowerCase();
  return `${Date.now()}-${crypto.randomBytes(12).toString('hex')}${ext}`;
}
async function uploadFile(file, kind = 'public', folder = '') {
  if (!file?.buffer) return null;
  const name = storageFilename(file);
  const storagePath = folder ? `${folder}/${name}` : name;
  const { error } = await supabase.storage.from(storageBucket(kind)).upload(storagePath, file.buffer, { contentType: file.mimetype, upsert: false });
  if (error) throw error;
  return storagePath;
}
async function deleteFile(kind, filename) {
  if (!filename) return;
  const { error } = await supabase.storage.from(storageBucket(kind)).remove([filename]);
  if (error) console.warn('Storage delete failed:', error.message);
}
function publicFileUrl(filename) {
  if (!filename) return null;
  return supabase.storage.from(PUBLIC_BUCKET).getPublicUrl(filename).data.publicUrl;
}
async function privateFileUrl(filename, expiresIn = 300) {
  const { data, error } = await supabase.storage.from(PRIVATE_BUCKET).createSignedUrl(filename, expiresIn);
  if (error) throw error;
  return data.signedUrl;
}
function filePath(kind, filename) { return filename ? filename : null; }
function locatePlayerFile(filename, kind) { return filename || null; }
function mimeFromPath(fp) { const e = path.extname(fp || '').toLowerCase(); return e === '.pdf' ? 'application/pdf' : e === '.png' ? 'image/png' : 'image/jpeg'; }
function blobForUpload(file) { return file?.buffer || null; }

async function sendPlayerAsset(res, p, field) {
  const filename = p[field];
  if (!filename) return res.status(404).json({ error: 'File not found.' });
  try {
    if (field === 'document') {
      res.setHeader('Content-Disposition', 'inline; filename="' + path.basename(filename) + '"');
      return res.redirect(await privateFileUrl(filename, 300));
    }
    return res.redirect(publicFileUrl(filename));
  } catch (e) {
    console.error('Storage asset error:', e);
    return res.status(404).json({ error: 'File not found.' });
  }
}
function removeFile(kind, filename) { void deleteFile(kind, filename); }
function removeUploadedFiles(files) {/* multer memoryStorage: nothing is written locally */ }
function fileAvailable(row, field) { return !!row?.[field]; }
async function backfillPlayerBlobs() {/* legacy SQLite blob backfill is intentionally unnecessary with Supabase Storage */ }
function validateSignature(file, kind) {
  if (!file?.buffer) return false;
  const b = file.buffer;
  const jpg = b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff;
  const pdf = b.subarray(0, 4).toString('ascii') === '%PDF';
  if (kind === 'photo' || kind === 'logo' || kind === 'gallery') return jpg;
  if (kind === 'document' || kind === 'rulebook') return pdf || jpg;
  return true;
}

const ADMIN_ID = process.env.ADMIN_ID, ADMIN_PASSWORD = process.env.ADMIN_PASSWORD;
