function admin(req, res, next) { if (req.session.user?.role !== 'admin') return res.status(403).json({ error: 'Admin only' }); next() }
function team(req, res, next) { if (req.session.user?.role !== 'team') return res.status(401).json({ error: 'Team login required' }); next() }
function emailTransport() { const u = process.env.GFL_EMAIL_USER, p = process.env.GFL_EMAIL_APP_PASSWORD; if (!u || !p) return null; return nodemailer.createTransport({ host: 'smtp.gmail.com', port: 465, secure: true, auth: { user: u, pass: p } }) }
async function sendMail(to, subject, text) { const tr = emailTransport(); if (!tr || !to) return false; try { await tr.sendMail({ from: process.env.GFL_EMAIL_FROM || process.env.GFL_EMAIL_USER, to, subject, text }); return true } catch (e) { console.error('Mail:', e.message); return false } }
function clean(v) { return String(v || '').trim() }
const loginAttempts = new Map();
function rateLimit(key, limit, windowMs) { const now = Date.now(); let a = loginAttempts.get(key) || []; a = a.filter(t => t > now - windowMs); if (a.length >= limit) { loginAttempts.set(key, a); return false } a.push(now); loginAttempts.set(key, a); return true }
setInterval(async () => { try { const cutoff = Date.now() - 60 * 60 * 1000; for (const [k, a] of loginAttempts) { const n = a.filter(t => t > cutoff); if (n.length) loginAttempts.set(k, n); else loginAttempts.delete(k) } await db.prepare('DELETE FROM sessions WHERE expires_at IS NOT NULL AND expires_at<?').run(Date.now()) } catch (e) { console.warn('Session cleanup:', e.message) } }, 15 * 60 * 1000).unref();

