app.post('/api/login', async (req, res) => {
  const key = (req.ip || 'unknown') + '|' + clean(req.body.code).toLowerCase(); if (!rateLimit(key, 10, 15 * 60 * 1000)) return res.status(429).json({ error: 'Too many login attempts. Please try again later.' }); const code = clean(req.body.code), password = String(req.body.password || '');
  if (code === ADMIN_ID && password === ADMIN_PASSWORD) { req.session.user = { id: 0, name: 'GFL Management', code: ADMIN_ID, role: 'admin' }; return res.json(req.session.user) }
  const u = await db.prepare('SELECT * FROM teams WHERE lower(team_code)=lower(?) AND active=1').get(code);
  if (!u || !bcrypt.compareSync(password, u.password_hash)) return res.status(401).json({ error: 'Invalid Team ID or password.' });
  req.session.user = { id: u.id, name: u.team_name, code: u.team_code, role: 'team' }; res.json(req.session.user);
});
