app.get('/api/private/player/:id/:kind', async (req, res) => {

  if (!['admin', 'team'].includes(req.session.user?.role)) {
    console.warn('[PRIVATE PHOTO] Unauthorized');
    return res.status(401).json({ error: 'Login required' });
  }

  const p = await db.prepare(
    'SELECT * FROM players WHERE id=?'
  ).get(Number(req.params.id));

  if (!p) {
    console.warn('[PRIVATE PHOTO] Player not found');
    return res.status(404).json({ error: 'Player not found' });
  }

  if (
    req.session.user.role === 'team' &&
    p.team_id !== req.session.user.id
  ) {
    console.warn('[PRIVATE PHOTO] Forbidden - wrong team');
    return res.status(403).json({ error: 'Forbidden' });
  }

  const field =
    req.params.kind === 'document'
      ? 'document'
      : req.params.kind === 'photo'
        ? 'photo'
        : null;

  console.log('[PRIVATE PHOTO] Resolved field:', field);

  if (!field || (!p[field] && !p[field + '_data'])) {
    console.warn('[PRIVATE PHOTO] File not found:', {
      field,
      file: p[field],
      data: !!p[field + '_data']
    });

    return res.status(404).json({ error: 'File not found' });
  }

  if (field === 'document') {
    res.setHeader(
      'Content-Disposition',
      'inline; filename="' +
      path.basename(p[field] || 'player-document') +
      '"'
    );
  }

  console.log('[PRIVATE PHOTO] Calling sendPlayerAsset()');

  return sendPlayerAsset(res, p, field);
});


app.get('/api/public/player/:id/photo', async (req, res) => {


  const p = await db.prepare(`
    SELECT
      photo,
      photo_data,
      photo_mime,
      status
    FROM players
    WHERE id = ?
      AND status = 'Approved'
  `).get(Number(req.params.id));

  if (!p) {
    console.warn('[PUBLIC PHOTO] Player not found or not approved');
    return res.status(404).send('Player not found');
  }

  if (!p.photo && !p.photo_data) {
    console.warn('[PUBLIC PHOTO] No photo data exists');

    return res.status(404).send('Photo not found');
  }

  try {

    const result = sendPlayerAsset(res, p, 'photo');

    return result;

  } catch (err) {

    return res.status(500).send('Unable to load photo');
  }
});

app.get('/api/player-profile/:id', async (req, res) => {

  const p = await db.prepare(`
    SELECT
      p.id,
      p.team_id,
      p.name,
      p.dob,
      p.age,
      p.mobile,
      p.jersey,
      p.position,
      p.photo,
      p.photo_data,
      p.photo_mime,
      p.status,
      p.created_at,
      t.team_name,
      x.matches,
      x.goals,
      x.assists,
      x.tackles,
      x.minutes
    FROM players p
    JOIN teams t ON t.id = p.team_id
    LEFT JOIN stats x ON x.player_id = p.id
    WHERE p.id = ?
      AND p.status = 'Approved'
  `).get(Number(req.params.id));

  if (!p) {
    console.warn('[PROFILE] Player not found or not approved');

    return res.status(404).json({
      error: 'Player not found or not approved'
    });
  }


  p.league_year = (await settings()).league_year;

  p.photo_available = !!(p.photo || p.photo_data);

  // Don't send image data to browser
  delete p.photo_data;

  // Don't need this in profile JSON
  delete p.photo_mime;

  res.json(p);
});


