app.get('/api/team/:id', async (req, res) => {
  try {
    const t = await db.prepare(
      'SELECT id,team_code,team_name,logo,short_name,area,manager,description,group_name FROM teams WHERE id=? AND active=1'
    ).get(+req.params.id);

    if (!t) {
      return res.status(404).json({ error: 'Team not found' });
    }

    const players = await db.prepare(`
      SELECT
        p.id,
        p.name,
        p.jersey,
        p.position,
        p.photo,
        p.photo_data,
        p.status,
        x.matches,
        x.goals,
        x.assists,
        x.tackles,
        x.minutes
      FROM players p
      LEFT JOIN stats x ON x.player_id = p.id
      WHERE p.team_id = ?
        AND p.status = 'Approved'
      ORDER BY p.name
    `).all(t.id);

    t.players = players.map(p => {
      const photo_available = fileAvailable(p, 'photo');

      delete p.photo_data;

      return {
        ...p,
        photo_available
      };
    });

    res.json(t);

  } catch (e) {
    console.error('TEAM PROFILE ERROR:', e);

    res.status(500).json({
      error: e.message || 'Unable to load team profile.'
    });
  }
});



