app.get('/api/standings', async (req, res) => { const teams = await db.prepare('SELECT id,team_name,logo,group_name FROM teams WHERE active=1 ORDER BY team_name').all(); const out = teams.map(t => ({ ...t, played: 0, won: 0, draw: 0, lost: 0, gf: 0, ga: 0, gd: 0, points: 0 })), m = Object.fromEntries(out.map(x => [x.id, x])); for (const f of await db.prepare("SELECT * FROM fixtures WHERE status='Completed'").all()) { const a = m[f.team1_id], b = m[f.team2_id]; if (!a || !b || f.score1 == null || f.score2 == null) continue; const x = +f.score1, y = +f.score2; a.played++; b.played++; a.gf += x; a.ga += y; b.gf += y; b.ga += x; if (x > y) { a.won++; a.points += 3; b.lost++ } else if (x < y) { b.won++; b.points += 3; a.lost++ } else { a.draw++; b.draw++; a.points++; b.points++ } } out.forEach(x => x.gd = x.gf - x.ga); out.sort((a, b) => b.points - a.points || b.gd - a.gd || b.gf - a.gf); res.json(out) });

app.post(
  '/api/team-registration',

  upload.fields([
    { name: 'logo', maxCount: 1 },
    { name: 'document', maxCount: 1 }
  ]),

  async (req, res) => {

    let stage = 'START';

    try {

      console.log('\n========================================');
      console.log('TEAM REGISTRATION REQUEST');
      console.log('========================================');

      stage = 'FILES';

      const f = req.files || {};

      const logo = f.logo?.[0];
      const document = f.document?.[0];

      console.log('[1] Files received:', {
        logo: !!logo,
        document: !!document
      });


      // ----------------------------------------
      // SETTINGS / DATABASE READ
      // ----------------------------------------

      stage = 'DATABASE_SETTINGS';

      console.log('[2] Reading settings from PostgreSQL...');

      const s = await settings();

      console.log('[2] Settings loaded:', {
        registration_open: s.registration_open,
        league_year: s.league_year
      });


      const b = req.body;

      console.log('[3] Form received:', {
        teamName: b.teamName,
        shortName: b.shortName,
        area: b.area,
        manager: b.manager,
        contact: b.contact,
        email: b.email,
        hasPassword: !!b.password,
        declaration: b.declaration
      });


      // ----------------------------------------
      // FILE VALIDATION
      // ----------------------------------------

      stage = 'VALIDATE_LOGO';

      if (logo && !validateSignature(logo, 'logo')) {

        console.log('[4] Invalid logo');

        removeUploadedFiles(f);

        return res.status(400).json({
          error: 'Team logo must be a valid JPG/JPEG image.'
        });
      }


      stage = 'VALIDATE_DOCUMENT';

      if (document && !validateSignature(document, 'document')) {

        console.log('[5] Invalid document');

        removeUploadedFiles(f);

        return res.status(400).json({
          error: 'Team document must be a valid JPG/JPEG/PDF file.'
        });
      }


      // ----------------------------------------
      // REGISTRATION STATUS
      // ----------------------------------------

      stage = 'REGISTRATION_STATUS';

      if (s.registration_open !== '1') {

        console.log('[6] Registration is closed');

        return res.status(403).json({
          error: s.registration_closed_message
        });
      }


      // ----------------------------------------
      // REQUIRED FIELDS
      // ----------------------------------------

      stage = 'VALIDATE_FIELDS';

      for (const k of [
        'teamName',
        'area',
        'manager',
        'contact',
        'email',
        'password',
        'declaration'
      ]) {

        if (!clean(b[k])) {

          console.log('[7] Missing required field:', k);

          return res.status(400).json({
            error: 'Please complete all required fields.'
          });
        }
      }


      // ----------------------------------------
      // DECLARATION
      // ----------------------------------------

      stage = 'VALIDATE_DECLARATION';

      if (b.declaration !== 'accepted') {

        console.log('[8] Declaration not accepted');

        return res.status(400).json({
          error: 'You must accept the declaration.'
        });
      }


      // ----------------------------------------
      // PASSWORD
      // ----------------------------------------

      stage = 'VALIDATE_PASSWORD';

      if (String(b.password).length < 6) {

        console.log('[9] Password too short');

        return res.status(400).json({
          error: 'Password must be at least 6 characters.'
        });
      }


      // ----------------------------------------
      // DUPLICATE TEAM CHECK
      // ----------------------------------------

      stage = 'CHECK_EXISTING_TEAM';

      console.log('[10] Checking existing team...');

      const existingTeam = await db
        .prepare(
          'SELECT id FROM teams WHERE lower(team_code)=lower(?)'
        )
        .get(clean(b.email));

      console.log('[10] Existing team:', !!existingTeam);


      // ----------------------------------------
      // DUPLICATE APPLICATION CHECK
      // ----------------------------------------

      stage = 'CHECK_EXISTING_APPLICATION';

      console.log('[11] Checking existing application...');

      const existingApplication = await db
        .prepare(
          "SELECT id FROM team_applications WHERE lower(email)=lower(?) AND status NOT IN ('Rejected')"
        )
        .get(clean(b.email));

      console.log(
        '[11] Existing application:',
        !!existingApplication
      );


      if (existingTeam || existingApplication) {

        console.log('[12] DUPLICATE EMAIL');

        return res.status(400).json({
          error: 'This email is already registered.'
        });
      }


      // ----------------------------------------
      // REGISTRATION NUMBER
      // ----------------------------------------

      stage = 'GENERATE_REGISTRATION_NUMBER';

      const reg =
        `GFL-${s.league_year}-T${Date.now()
          .toString()
          .slice(-8)}`;

      console.log('[13] Registration number:', reg);


      // ----------------------------------------
      // CORRECTION TOKEN
      // ----------------------------------------

      stage = 'GENERATE_TOKEN';

      const token =
        crypto.randomBytes(24).toString('hex');


      // ----------------------------------------
      // PASSWORD HASH
      // ----------------------------------------

      stage = 'HASH_PASSWORD';

      const passwordHash =
        bcrypt.hashSync(
          String(b.password),
          12
        );

      console.log('[14] Password hashed successfully');


      // ----------------------------------------
      // UPLOAD LOGO
      // ----------------------------------------

      let logoPath = null;

      if (logo) {

        stage = 'UPLOAD_LOGO';

        console.log('[15] Uploading logo to Supabase Storage...');

        logoPath = await uploadFile(
          logo,
          'public',
          'teams/logos'
        );

        console.log(
          '[15] Logo uploaded:',
          !!logoPath
        );
      }


      // ----------------------------------------
      // UPLOAD DOCUMENT
      // ----------------------------------------

      let documentPath = null;

      if (document) {

        stage = 'UPLOAD_DOCUMENT';

        console.log(
          '[16] Uploading document to Supabase Storage...'
        );

        documentPath = await uploadFile(
          document,
          'private',
          'team-documents'
        );

        console.log(
          '[16] Document uploaded:',
          !!documentPath
        );
      }


      // ----------------------------------------
      // DATABASE INSERT
      // ----------------------------------------

      stage = 'INSERT_APPLICATION';

      console.log(
        '[17] Inserting team application into PostgreSQL...'
      );

      const result = await db
        .prepare(
          `INSERT INTO team_applications(
            reg_no,
            team_name,
            short_name,
            area,
            manager,
            contact,
            email,
            description,
            logo,
            document,
            password_hash,
            status,
            correction_token,
            updated_at
          )
          VALUES(
            ?,?,?,?,?,?,?,?,?,?,?, 'Pending', ?, CURRENT_TIMESTAMP
          )`
        )
        .run(
          reg,
          b.teamName,
          b.shortName,
          b.area,
          b.manager,
          b.contact,
          b.email,
          b.description,
          logoPath,
          documentPath,
          passwordHash,
          token
        );

      console.log(
        '[17] PostgreSQL INSERT successful:',
        result
      );


      // ----------------------------------------
      // VERIFY DATABASE WRITE
      // ----------------------------------------

      stage = 'VERIFY_INSERT';

      console.log(
        '[18] Verifying inserted application...'
      );

      const inserted = await db
        .prepare(
          'SELECT id, reg_no, email, status FROM team_applications WHERE reg_no=?'
        )
        .get(reg);

      console.log(
        '[18] Verification result:',
        inserted
      );


      if (!inserted) {

        throw new Error(
          'Application was inserted but could not be read back from PostgreSQL.'
        );
      }


      // ----------------------------------------
      // EMAIL
      // ----------------------------------------

      stage = 'SEND_EMAIL';

      console.log(
        '[19] Sending registration email...'
      );

      const emailResult = await sendMail(
        b.email,
        'GFL 2026 - Registration Received',
        `Your GFL team registration ${reg} has been received. Your login ID is your registered Gmail. Your password is not sent by email. Wait for Admin approval.`
      );

      console.log(
        '[19] Email result:',
        emailResult
      );


      // ----------------------------------------
      // SUCCESS
      // ----------------------------------------

      stage = 'COMPLETE';

      console.log(
        '[20] TEAM REGISTRATION SUCCESS:',
        reg
      );

      console.log(
        '========================================\n'
      );

      return res.json({
        ok: true,
        registration: reg
      });


    } catch (e) {

      console.error('\n========================================');
      console.error('TEAM REGISTRATION FAILED');
      console.error('STAGE:', stage);
      console.error('ERROR:', e);
      console.error('MESSAGE:', e?.message);
      console.error('STACK:', e?.stack);
      console.error('========================================\n');


      try {
        removeUploadedFiles(req.files);
      } catch (cleanupError) {
        console.error(
          'Upload cleanup error:',
          cleanupError
        );
      }


      return res.status(500).json({
        ok: false,
        error: 'Registration failed.',
        stage: stage,
        details:
          process.env.NODE_ENV === 'production'
            ? undefined
            : e?.message
      });
    }
  }
);


