app.post('/api/admin/stats', admin, async (req, res) => {
  try {
    const keys = [
      'matches',
      'starts',
      'goals',
      'assists',
      'passes',
      'key_passes',
      'shots',
      'tackles',
      'interceptions',
      'yellow',
      'red',
      'minutes'
    ];

    const playerId = Number(req.body?.playerId);

    if (!Number.isInteger(playerId) || playerId < 1) {
      return res.status(400).json({
        error: 'Invalid player ID.'
      });
    }

    const player = await db
      .prepare('SELECT id FROM players WHERE id=?')
      .get(playerId);

    if (!player) {
      return res.status(404).json({
        error: 'Player not found.'
      });
    }

    // Empty, missing, invalid or negative values become 0.
    // A real 0 remains 0.
    const vals = keys.map(k => {
      const n = Number(req.body?.[k]);

      return Number.isFinite(n) && n >= 0
        ? Math.floor(n)
        : 0;
    });

    // player_id + 12 statistic fields = 13 placeholders
    const placeholders = ['?'].concat(keys.map(() => '?')).join(',');

    await db.prepare(`
      INSERT INTO stats (
        player_id,
        ${keys.join(',')}
      )
      VALUES (${placeholders})
      ON CONFLICT(player_id) DO UPDATE SET
        ${keys.map(k => `${k}=excluded.${k}`).join(',')}
    `).run(playerId, ...vals);

    const updated = await db
      .prepare(`
        SELECT ${keys.join(',')}
        FROM stats
        WHERE player_id=?
      `)
      .get(playerId);

    log(
      req.session.user.name,
      'Updated statistics for player #' + playerId
    );

    res.json({
      ok: true,
      stats: updated
    });

  } catch (e) {
    console.error('Statistics update failed:', e);

    res.status(400).json({
      error: e.message || 'Statistics update failed.'
    });
  }
});


