app.post(
  '/api/admin/player',
  admin,
  playerUpload.fields([
    { name: 'photo', maxCount: 1 },
    { name: 'document', maxCount: 1 }
  ]),
  async (req, res) => {
    const b = req.body || {};
    const f = req.files || {};

    const photo = f.photo?.[0];
    const document = f.document?.[0];

    try {
      // ----------------------------------------
      // VALIDATE FILES
      // ----------------------------------------

      if (
        photo &&
        !validateSignature(photo, 'photo')
      ) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error:
            'Player photo file is invalid. Please select a real JPG/JPEG image.'
        });
      }

      if (
        document &&
        !validateSignature(document, 'document')
      ) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error:
            'Player document file is invalid. Please select a real JPG/JPEG/PDF file.'
        });
      }

      // ----------------------------------------
      // REQUIRED FIELDS
      // ----------------------------------------

      if (!clean(b.name)) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error: 'Player name is required.'
        });
      }

      if (!b.teamId || !Number.isInteger(+b.teamId)) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error: 'Please select a team.'
        });
      }

      if (!b.dob) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error: 'Date of birth is required.'
        });
      }

      if (!clean(b.position)) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error: 'Player position is required.'
        });
      }

      // ----------------------------------------
      // VERIFY TEAM
      // ----------------------------------------

      const team = await db
        .prepare(
          `SELECT id, team_name
           FROM teams
           WHERE id=? AND active=1`
        )
        .get(+b.teamId);

      if (!team) {
        removeUploadedFiles(f);

        return res.status(404).json({
          error: 'Selected team was not found or is inactive.'
        });
      }

      // ----------------------------------------
      // PLAYER LIMIT
      // ----------------------------------------

      const playerCount = (
        await db
          .prepare(
            `SELECT COUNT(*) AS count
             FROM players
             WHERE team_id=?`
          )
          .get(+b.teamId)
      ).count;

      if (playerCount >= 8) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error:
            'Maximum 8 players can be registered for one team.'
        });
      }

      // ----------------------------------------
      // CALCULATE AGE
      // ----------------------------------------

      const d = new Date(
        b.dob + 'T00:00:00'
      );

      const now = new Date();

      let age =
        now.getFullYear() -
        d.getFullYear();

      const month =
        now.getMonth() -
        d.getMonth();

      if (
        month < 0 ||
        (
          month === 0 &&
          now.getDate() < d.getDate()
        )
      ) {
        age--;
      }

      if (
        age < 1 ||
        age > 100
      ) {
        removeUploadedFiles(f);

        return res.status(400).json({
          error:
            'Please enter a valid date of birth.'
        });
      }

      // ----------------------------------------
      // OPTIONAL VALUES
      // ----------------------------------------

      const jersey =
        b.jersey !== '' &&
        b.jersey !== undefined &&
        b.jersey !== null &&
        Number.isFinite(+b.jersey)
          ? +b.jersey
          : null;

      const mobile =
        clean(b.mobile) || '';

      const documentNo =
        clean(b.documentNo) || null;

      // ----------------------------------------
      // UPLOAD FILES
      // ----------------------------------------

      const photoPath = photo
        ? await uploadFile(
            photo,
            'public',
            'players/photos'
          )
        : null;

      const documentPath = document
        ? await uploadFile(
            document,
            'private',
            'players/documents'
          )
        : null;

      // ----------------------------------------
      // CREATE PLAYER
      // ----------------------------------------

      const result = await db
        .prepare(
          `INSERT INTO players(
            team_id,
            name,
            dob,
            age,
            mobile,
            jersey,
            position,
            photo,
            document,
            document_no,
            photo_data,
            photo_mime,
            document_data,
            document_mime,
            status,
            correction_reason
          )
          VALUES(
            ?,?,?,?,?,?,?,?,?,?,
            ?,?,?,?,
            'Pending',
            NULL
          )`
        )
        .run(
          +b.teamId,
          clean(b.name),
          b.dob,
          age,
          mobile,
          jersey,
          clean(b.position),
          photoPath,
          documentPath,
          documentNo,
          null,
          null,
          null,
          null
        );

      const playerId =
        result.lastInsertRowid;

      // ----------------------------------------
      // CREATE EMPTY STATISTICS ROW
      // ----------------------------------------

      await db
        .prepare(
          `INSERT INTO stats(player_id)
           VALUES(?)
           ON CONFLICT(player_id)
           DO NOTHING`
        )
        .run(playerId);

      // ----------------------------------------
      // LOG
      // ----------------------------------------

      log(
        req.session.user.name,
        `Admin created player #${playerId} for team ${team.team_name}`
      );

      // ----------------------------------------
      // RESPONSE
      // ----------------------------------------

      const leagueSettings =
        await settings();

      const registration =
        `GFL-${leagueSettings.league_year}-${String(
          playerId
        ).padStart(4, '0')}`;

      return res.json({
        ok: true,
        id: playerId,
        registration,
        status: 'Pending',
        team: team.team_name
      });

    } catch (e) {

      console.error(
        'ADMIN PLAYER CREATION ERROR:',
        e
      );

      // Clean up uploaded files if
      // database insertion failed.
      try {
        removeUploadedFiles(f);
      } catch (cleanupError) {
        console.error(
          'Admin player upload cleanup error:',
          cleanupError
        );
      }

      return res.status(400).json({
        error:
          e.message ||
          'Unable to create player.'
      });
    }
  }
);